        PHPNEW[_rel] = (_txt.replace("\n", "\r\n") if _crlf else _txt).encode("utf-8"); PHPLIVE[_rel] = _live
        php_lint(PHPNEW[_rel], _rel + " (live text + the 1.72.401 film)")
